    pub fn drawing_mut(&self) -> RefMut<'_, Drawing> {
        // We're about to change graphics, so invalidate on the next frame
        self.invalidate_cached_bitmap();
        self.0.drawing.get_or_init(Default::default).borrow_mut()
    }

